#include <vector>
#include <algorithm>
#include <cmath>

namespace cg3 {
    template <class T>
    class Point2 {
    public:
        Point2(T x = 0.0, T y = 0.0) : xCoord(x), yCoord(y) {}
        const T& x() const { return xCoord; }
        const T& y() const { return yCoord; }
    private:
        T xCoord, yCoord;
    };

    template <class T>
    class Segment {
    public:
        Segment(const T& p1, const T& p2) : _p1(p1), _p2(p2) {}
        const T& p1() const { return _p1; }
        const T& p2() const { return _p2; }
    private:
        T _p1, _p2;
    };

    typedef Point2<double> Point2d;
    typedef Segment<Point2d> Segment2d;

    bool epsilonEqual(double x, double v, double epsilon = 1e-6) {
        return std::abs(x - v) < epsilon;
    }
}

std::vector<cg3::Point2d> segmentIntersections(const std::vector<cg3::Segment2d>& segments) {
    std::vector<cg3::Point2d> intersections;

    if (segments.size() < 2) {
        return intersections;
    }

    const double eps = 1e-6;

    for (size_t i = 0; i < segments.size(); ++i) {
        for (size_t j = i + 1; j < segments.size(); ++j) {
            const cg3::Segment2d& seg1 = segments[i];
            const cg3::Segment2d& seg2 = segments[j];

            cg3::Point2d p1 = seg1.p1();
            cg3::Point2d p2 = seg1.p2();
            cg3::Point2d p3 = seg2.p1();
            cg3::Point2d p4 = seg2.p2();

            double x1 = p1.x(), y1 = p1.y();
            double x2 = p2.x(), y2 = p2.y();
            double x3 = p3.x(), y3 = p3.y();
            double x4 = p4.x(), y4 = p4.y();

            double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);

            if (std::abs(denom) < eps) {
                continue;
            }

            double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
            double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;

            if (t >= -eps && t <= 1 + eps && u >= -eps && u <= 1 + eps) {
                double x = x1 + t * (x2 - x1);
                double y = y1 + t * (y2 - y1);

                bool duplicate = false;
                for (const auto& pt : intersections) {
                    if (cg3::epsilonEqual(pt.x(), x, eps) && cg3::epsilonEqual(pt.y(), y, eps)) {
                        duplicate = true;
                        break;
                    }
                }

                if (!duplicate) {
                    intersections.emplace_back(x, y);
                }
            }
        }
    }

    return intersections;
}

int main() {
    std::vector<cg3::Segment2d> segments;
    segments.emplace_back(cg3::Point2d(0, 0), cg3::Point2d(1, 1));
    segments.emplace_back(cg3::Point2d(0, 1), cg3::Point2d(1, 0));

    auto result = segmentIntersections(segments);
    return 0;
}

