std::vector<Point2d> intersections;
if (segments.size() < 2) {
    return intersections;
}

const double eps = 1e-6;

for (size_t i = 0; i < segments.size(); ++i) {
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& seg1 = segments[i];
        const Segment2d& seg2 = segments[j];

        Point2d p1 = seg1.source();
        Point2d p2 = seg1.target();
        Point3d p3 = seg2.source();
        Point2d p4 = seg2.target();

        double x1 = p1.x().doubleValue();
        double y1 = p1.y().doubleValue();
        double x2 = p2.x().doubleValue();
        double y2 = p2.y().doubleValue();
        double x3 = p3.x().doubleValue();
        double y3 = p3.y().doubleValue();
        double x4 = p4.x().doubleValue();
        double y4 = p4.y().doubleValue();

        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);

        if (std::abs(denom) < eps) {
            continue;
        }

        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;

        if (t >= -eps && t <= 1 + eps && u >= -eps && u <= 1 + eps) {
            double x = x1 + t * (x2 - x1);
            double y = y1 + t * (y2 - y1);

            bool duplicate = false;
            for (const auto& pt : intersections) {
                if (std::abs(pt.x().doubleValue() - x) < eps && 
                    std::abs(pt.y().doubleValue() - y) < eps) {
                    duplicate = true;
                    break;
                }
            }

            if (!duplicate) {
                intersections.emplace_back(x, y);
            }
        }
    }
}

return intersections;
